INSERT INTO `event_instance` (`n_id`, `n_event_template_id`, `n_product_id`, `n_service_id`, `str_event_label`, `str_product_name`, `str_service_abbr`, `str_service_region`, `str_category`, `str_type`, `str_event_name`, `str_input_values`, `str_generated_query`, `dt_deploy_date`, `dt_qa_deploy_date`, `dt_live_deploy_date`, `str_allo_link`, `str_status`, `str_created_by`, `n_created_by_user_id`, `dt_created_at`, `b_permanently_removed`, `dt_permanently_removed_at`) VALUES
	(1, 1, 1, 1, '[FH] 쿼리 테스트', '출조낚시왕', 'FH', '국내', '아이템', '초기화', '[FH] 7월 1일, 쿼리 테스트', '123456', 'select 123 as \'col2\';', '2026-07-01 06:00:00.000000', '2026-07-01 06:00:00.000000', '2026-07-01 08:00:00.000000', NULL, 'live_requested', '관리자', 1, '2026-07-01 19:41:52.890000', 0, NULL),
	(2, 2, 4, 5, '[AD/G] 5~6월 이벤트 아이템 삭제 요청', '아스다글로벌', 'AD/G', '글로벌', '아이템', '삭제', '[AD] 7월 8일, [AD/G] 5~6월 이벤트 아이템 삭제 요청', '81259\n81260\n81261\n81262\n80921', '--아이템 삭제 준비\n\n/*\n점검 일정: 2026.07.07 (화) 15:00\n​\n점검시 전월 이벤트 아이템 삭제가 필요하여 요청드립니다.\n해당 아이템들은 아래와 같습니다.\n\n81259	^[E]Blue Candle^\n81260	^[E]Green Candle^\n81261	^[E]Yellow Candle^\n81262	^[E]Red Candle^\n80921	^[E]Celebration Coin^\n\n잘 부탁드립니다!\n\n+ 2023.12.08\n	- 삭제된 행 수가 동일하면 커밋하도록 수정하였습니다.\n	- @IsCommit 변수가 1 일 경우 커밋하도록 수정하였습니다.\n*/\n\nUSE [Joy1]\n\nBEGIN TRANSACTION\n\nDECLARE @IsCommit TINYINT = 1;		/*** 라이브 적용 시 값 변경 부탁드립니다 : [1] ***/\nDECLARE @IsPrintQuery TINYINT = 0;\n\nDECLARE @InputString NVARCHAR(1000) = \'81259, 81260, 81261, 81262, 80921\';\n\nDECLARE @TODAY NVARCHAR(20) = CONVERT(VARCHAR(8), getdate(), 112)\nDECLARE @MyTempTable TABLE (MyItemIndex INT)\nDECLARE @Value INT, @pos INT\n\n-- 제거 아이템\nIF EXISTS( SELECT TABLE_NAME FROM tempdb.INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME LIKE \'%DeleteItem\' )\n	DROP TABLE ##DeleteItem\nCREATE TABLE ##DeleteItem (\n	MyItemIndex	INT\n)\n\n-- 대상 테이블\nIF EXISTS( SELECT TABLE_NAME FROM tempdb.INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME LIKE \'%TargetTable\' )\n	DROP TABLE ##TargetTable\nCREATE TABLE ##TargetTable (\n	TableName		NVARCHAR(64)		-- 테이블 명칭\n,	IsBackup		TINYINT				-- 백업 여부		( 0 / 1 )\n,	IsClear			TINYINT				-- 아이템 제거 여부	( 0 / 1 )\n,	SourceItemCount	BIGINT	DEFAULT(0)	-- 삭제 전 아이템 개수\n,	DeleteItemCount BIGINT	DEFAULT(0)	-- 삭제된 아이템 개수\n)\n\nWHILE CHARINDEX(\',\', @InputString) <> 0\nBEGIN\n	SET @pos = CHARINDEX(\',\', @InputString)\n	SET @Value = CAST(SUBSTRING(@InputString, 1, @pos-1) AS INT)\n	INSERT INTO ##DeleteItem(MyItemIndex) VALUES(@Value)\n	SET @InputString = SUBSTRING(@InputString, @pos+1, LEN(@InputString)-@pos)\nEND\nSET @Value = CAST(SUBSTRING(@InputString, 1, LEN(@InputString)) AS INT)\nINSERT INTO ##DeleteItem(MyItemIndex) VALUES(@Value)\n\nINSERT INTO ##TargetTable(IsBackup, IsClear, TableName) VALUES \n	(1, 1, \'Item\')				-- 인벤&창고\n,	(1, 1, \'Exitem\')			-- 거래소\n,	(1, 1, \'ItemPostbox\')		-- 우편함\n,	(1, 0, \'PostExpress\')		-- 개인우편함 : 아이템 제거사항 없음\n,	(1, 1, \'PostExpressItem\')	-- 개인우편함아이템\n\n--- 테이블 백업 ---\nDECLARE @DQuery_Backup NVARCHAR(MAX) = \'\';\nSELECT @DQuery_Backup = CONCAT( @DQuery_Backup, \'\n	IF EXISTS( SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = \'\'\', TableName, \'_\', @TODAY,\'\'\')\n		DROP TABLE dbo.\', TableName,\'_\', @TODAY, \'\n	SELECT * INTO dbo.\', TableName,\'_\', @TODAY, \' FROM \', TableName, \' WITH (TABLOCK)\n	\')\n	FROM ##TargetTable\n		WHERE IsBackup = 1;\n\nIF(@IsPrintQuery = 1) PRINT @DQuery_Backup\nEXEC sp_ExecuteSql @DQuery_Backup;\n\n--- 조회 시작 ---\nDECLARE @DQuery_SaveSourceItemCount NVARCHAR(MAX) = \'\';\nSELECT @DQuery_SaveSourceItemCount = CONCAT( @DQuery_SaveSourceItemCount, \'\n	UPDATE ##TargetTable SET\n		SourceItemCount = [_CurTable].ItemCount\n	FROM ( SELECT COUNT(*) AS [ItemCount]\n			FROM \', TableName, \' \n				WHERE Code IN ( SELECT MyItemIndex FROM ##DeleteItem ) ) AS [_CurTable]\n		WHERE TableName = \'\'\', TableName, \'\'\'\n	\')\n	FROM ##TargetTable\n		WHERE IsClear = 1;\n		\nIF(@IsPrintQuery = 1) PRINT @DQuery_SaveSourceItemCount\nEXEC sp_ExecuteSql @DQuery_SaveSourceItemCount;\n\n--- 삭제 시작 ---\nBEGIN TRY\n\nDECLARE @DQuery_DeleteItem NVARCHAR(MAX) = \'\';\nSELECT @DQuery_DeleteItem = CONCAT( @DQuery_DeleteItem, \'\n	DELETE FROM \', TableName, \'\n		WHERE Code IN ( SELECT MyItemIndex FROM ##DeleteItem )\n\n	-- 삭제된 아이템 개수 입력\n	UPDATE ##TargetTable SET\n		DeleteItemCount = @@ROWCOUNT\n	WHERE TableName = \'\'\', TableName, \'\'\'\n	\')\n	FROM ##TargetTable\n		WHERE IsClear = 1;\n\nIF(@IsPrintQuery = 1) PRINT @DQuery_DeleteItem\nEXEC sp_ExecuteSql @DQuery_DeleteItem;\n\n-- 개인 우편함은 별도 처리\nUPDATE postExpress SET Itemorder=-1 WHERE ItemOrder IN (SELECT Orderidx FROM dbo.PostExpressItem WITH(NOLOCK) \nWHERE code IN (SELECT MyItemIndex FROM ##DeleteItem))\n\nEND TRY\nBEGIN CATCH\n\nIF @@ERROR <> 0\nBEGIN\n	PRINT \'** Error on delete **\'\n	ROLLBACK TRANSACTION\n	RETURN\nEND\nEND CATCH\n--삭제 작업 종료-\n\n-- 삭제 결과 출력\nSELECT	TableName\n	,	SourceItemCount AS \'기존 아이템 개수\'\n	,	DeleteItemCount AS \'삭제된 아이템 개수\'\n	FROM ##TargetTable\n		WHERE IsClear = 1\n\n-- 조회와 삭제 결과가 동일한지 비교\nDECLARE @IsComplate TINYINT = 1;\nSELECT @IsComplate = 0\n	FROM ##TargetTable\n		WHERE	IsClear = 1\n			AND SourceItemCount != DeleteItemCount\n\n-- 임시 테이블 제거\nIF EXISTS( SELECT TABLE_NAME FROM tempdb.INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME LIKE \'%DeleteItem\' )\n	DROP TABLE ##DeleteItem\nIF EXISTS( SELECT TABLE_NAME FROM tempdb.INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME LIKE \'%TargetTable\' )\n	DROP TABLE ##TargetTable	\n\n-- 조회 결과가 정상적이라면 커밋\nIF( @IsComplate = 1 AND @IsCommit = 1 )\nBEGIN\n	SELECT \'Run complate\' AS \'Do : COMMIT\';\n	COMMIT TRANSACTION\nEND\nELSE\nBEGIN\n	SELECT IIF( @IsCommit = 1, \'Error on delete\', \'Commit canceled ( @IsCommit = 0 )\') AS \'Do : ROLLBACK\';\n	ROLLBACK TRANSACTION\nEND', '2026-07-08 06:00:00.000000', '2026-07-08 06:00:00.000000', '2026-07-08 10:00:00.000000', NULL, 'live_requested', '관리자', 1, '2026-07-08 15:21:41.075000', 0, NULL),
	(3, 7, 8, 11, '출석 초기화', '건즈온라인', 'GZ/KR', '국내', '퀘스트', '초기화', '[GZ] 7월 22일, 출석 초기화', '0', 'USE `gunzgame`;\n\n-- 0\n\nDROP TABLE IF EXISTS `Attendence_Temp`;\n\nRENAME TABLE `Attendence` TO `Attendence_Temp`;\n\nCREATE TABLE `Attendence` LIKE `Attendence_Temp`;', '2026-07-22 15:00:00.000000', '2026-07-22 15:00:00.000000', '2026-07-23 10:00:00.000000', 'https://allo.io/c62993405fcb0d428e088baf76ed?page=cGFnZTo4MjExNzgwOjA', 'live_deployed', '문보성', 15, '2026-07-22 14:54:47.956000', 0, NULL);
