(SUBSTRING(@InputString, 1, @pos-1) AS INT)\\n\\tINSERT INTO ##DeleteItem(MyItemIndex) VALUES(@Value)\\n\\tSET @InputString = SUBSTRING(@InputString, @pos+1, LEN(@InputString)-@pos)\\nEND\\nSET @Value = CAST(SUBSTRING(@InputString, 1, LEN(@InputString)) AS INT)\\nINSERT INTO ##DeleteItem(MyItemIndex) VALUES(@Value)\\n\\nINSERT INTO ##TargetTable(IsBackup, IsClear, TableName) VALUES \\n\\t(1, 1, \'Item\')\\t\\t\\t\\t-- 인벤&창고\\n,\\t(1, 1, \'Exitem\')\\t\\t\\t-- 거래소\\n,\\t(1, 1, \'ItemPostbox\')\\t\\t-- 우편함\\n,\\t(1, 0, \'PostExpress\')\\t\\t-- 개인우편함 : 아이템 제거사항 없음\\n,\\t(1, 1, \'PostExpressItem\')\\t-- 개인우편함아이템\\n\\n--- 테이블 백업 ---\\nDECLARE @DQuery_Backup NVARCHAR(MAX) = \'\'", "nSetIndex": 1, "nSetTotal": 1, "nAffectedRows": 1}, {"nIndex": 4, "strQuery": "SELECT @DQuery_Backup = CONCAT( @DQuery_Backup, \'\\n\\tIF EXISTS( SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = \'\'\', TableName, \'_\', @TODAY,\'\'\')\\n\\t\\tDROP TABLE dbo.\', TableName,\'_\', @TODAY, \'\\n\\tSELECT * INTO dbo.\', TableName,\'_\', @TODAY, \' FROM \', TableName, \' WITH (TABLOCK)\\n\\t\')\\n\\tFROM ##TargetTable\\n\\t\\tWHERE IsBackup = 1", "nSetIndex": 1, "nSetTotal": 1, "nAffectedRows": 1}, {"nIndex": 5, "strQuery": "IF(@IsPrintQuery = 1) PRINT @DQuery_Backup\\nEXEC sp_ExecuteSql @DQuery_Backup", "nSetIndex": 1, "nSetTotal": 1, "nAffectedRows": 1}, {"nIndex": 6, "strQuery": "--- 조회 시작 ---\\nDECLARE @DQuery_SaveSourceItemCount NVARCHAR(MAX) = \'\'", "nSetIndex": 1, "nSetTotal": 1, "nAffectedRows": 1}, {"nIndex": 7, "strQuery": "SELECT @DQuery_SaveSourceItemCount = CONCAT( @DQuery_SaveSourceItemCount, \'\\n\\tUPDATE ##TargetTable SET\\n\\t\\tSourceItemCount = [_CurTable].ItemCount\\n\\tFROM ( SELECT COUNT(*) AS [ItemCount]\\n\\t\\t\\tFROM \', TableName, \' \\n\\t\\t\\t\\tWHERE Code IN ( SELECT MyItemIndex FROM ##DeleteItem ) ) AS [_CurTable]\\n\\t\\tWHERE TableName = \'\'\', TableName, \'\'\'\\n\\t\')\\n\\tFROM ##TargetTable\\n\\t\\tWHERE IsClear = 1", "nSetIndex": 1, "nSetTotal": 1, "nAffectedRows": 1}, {"nIndex": 8, "strQuery": "IF(@IsPrintQuery = 1) PRINT @DQuery_SaveSourceItemCount\\nEXEC sp_ExecuteSql @DQuery_SaveSourceItemCount", "nSetIndex": 1, "nSetTotal": 1, "nAffectedRows": 1}, {"nIndex": 9, "strQuery": "--- 삭제 시작 ---\\nBEGIN TRY\\n\\nDECLARE @DQuery_DeleteItem NVARCHAR(MAX) = \'\'", "nSetIndex": 1, "nSetTotal": 1, "nAffectedRows": 1}, {"nIndex": 10, "strQuery": "SELECT @DQuery_DeleteItem = CONCAT( @DQuery_DeleteItem, \'\\n\\tDELETE FROM \', TableName, \'\\n\\t\\tWHERE Code IN ( SELECT MyItemIndex FROM ##DeleteItem )\\n\\n\\t-- 삭제된 아이템 개수 입력\\n\\tUPDATE ##TargetTable SET\\n\\t\\tDeleteItemCount = @@ROWCOUNT\\n\\tWHERE TableName = \'\'\', TableName, \'\'\'\\n\\t\')\\n\\tFROM ##TargetTable\\n\\t\\tWHERE IsClear = 1", "nSetIndex": 1, "nSetTotal": 1, "nAffectedRows": 1}, {"nIndex": 11, "strQuery": "IF(@IsPrintQuery = 1) PRINT @DQuery_DeleteItem\\nEXEC sp_ExecuteSql @DQuery_DeleteItem", "nSetIndex": 1, "nSetTotal": 1, "nAffectedRows": 1}, {"nIndex": 12, "strQuery": "-- 개인 우편함은 별도 처리\\nUPDATE postExpress SET Itemorder=-1 WHERE ItemOrder IN (SELECT Orderidx FROM dbo.PostExpressItem WITH(NOLOCK) \\nWHERE code IN (SELECT MyItemIndex FROM ##DeleteItem))\\n\\nEND TRY\\nBEGIN CATCH\\n\\nIF @@ERROR <> 0\\nBEGIN\\n\\tPRINT \'** Error on delete **\'\\n\\tROLLBACK TRANSACTION\\n\\tRETURN\\nEND\\nEND CATCH\\n--삭제 작업 종료-\\n\\n-- 삭제 결과 출력\\nSELECT\\tTableName\\n\\t,\\tSourceItemCount AS \'기존 아이템 개수\'\\n\\t,\\tDeleteItemCount AS \'삭제된 아이템 개수\'\\n\\tFROM ##TargetTable\\n\\t\\tWHERE IsClear = 1\\n\\n-- 조회와 삭제 결과가 동일한지 비교\\nDECLARE @IsComplate TINYINT = 1", "nSetIndex": 1, "nSetTotal": 1, "nAffectedRows": 1}, {"nIndex": 13, "strQuery": "SELECT @IsComplate = 0\\n\\tFROM ##TargetTable\\n\\t\\tWHERE\\tIsClear = 1\\n\\t\\t\\tAND SourceItemCount != DeleteItemCount\\n\\n-- 임시 테이블 제거\\nIF EXISTS( SELECT TABLE_NAME FROM tempdb.INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME LIKE \'%DeleteItem\' )\\n\\tDROP TABLE ##DeleteItem\\nIF EXISTS( SELECT TABLE_NAME FROM tempdb.INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME LIKE \'%TargetTable\' )\\n\\tDROP TABLE ##TargetTable\\t\\n\\n-- 조회 결과가 정상적이라면 커밋\\nIF( @IsComplate = 1 AND @IsCommit = 1 )\\nBEGIN\\n\\tSELECT \'Run complate\' AS \'Do : COMMIT\'", "nSetIndex": 1, "nSetTotal": 1, "nAffectedRows": 1}, {"nIndex": 14, "strQuery": "COMMIT TRANSACTION\\nEND\\nELSE\\nBEGIN\\n\\tSELECT IIF( @IsCommit = 1, \'Error on delete\', \'Commit canceled ( @IsCommit = 0 )\') AS \'Do : ROLLBACK\'", "nSetIndex": 1, "nSetTotal": 1, "nAffectedRows": 1}, {"nIndex": 15, "strQuery": "ROLLBACK TRANSACTION\\nEND", "nSetIndex": 1, "nSetTotal": 1, "nAffectedRows": 1}], "nTotalAffectedRows": 16, "strConnectionSummary": "GAME | mssql | 18.205.215.160:1433/master"}', NULL),
