	(3, 2, 'DK온라인', '[DK/G] 아이템 일괄 삭제', '2026년 7월 21일 글로벌 아이템 삭제 쿼리입니다.', '아이템', '삭제', 'item_number', NULL, NULL, '기획-심현우', 2, '2026-07-09 18:01:37.772000', 'dba_confirmed', '[{"strStatus": "template_created", "strComment": "쿼리 템플릿 등록", "dtChangedAt": "2026-07-09T09:01:37.772Z", "strChangedBy": "기획-심현우", "nChangedByUserId": 2}, {"strStatus": "confirm_requested", "strComment": "", "dtChangedAt": "2026-07-09T09:05:05.499Z", "strChangedBy": "기획-심현우", "nChangedByUserId": 2}, {"strStatus": "confirm_requested", "strComment": "DBA 쿼리 리뷰 중 수정", "dtChangedAt": "2026-07-09T09:09:54.624Z", "objQueryEdit": {"arrSetChanges": [{"strAfter": "--아이템 삭제 쿼리\\n--전부 삭제\\n-- 적용 일자 : 2026-01-08\\n/*\\n--특정 서버만 적용할때 사용\\nDROP TABLE IF EXISTS ##__TargetWorld;\\nSELECT WorldID, ServerName\\n\\tINTO ##__TargetWorld\\nFROM dk_game_integrate.dbo.ConnectInfo\\nWHERE WorldID IN  -- 적용할 서버\\n\\t(\\n\\t\\t224\\n\\t  , 234\\n\\t  , 235\\n\\t  , 236\\n\\t  , 237\\n\\t  , 238\\n\\t  , 239\\n\\t  , 240\\n\\t)\\nORDER BY WorldID\\n*/\\n\\n--통합된 서버에 전부 적용할때 사용\\nDROP TABLE IF EXISTS ##__TargetWorld;\\nSELECT WorldID, ServerName\\n\\tINTO ##__TargetWorld\\nFROM dk_game_integrate.dbo.ConnectInfo\\nWHERE ServerGroupID IN  -- 적용할 서버 그룹\\n\\t(\\n\\t\\t50, 53\\n\\t)\\nORDER BY WorldID\\n\\nDROP TABLE IF EXISTS ##__UserCheck; \\nCREATE TABLE ##__UserCheck --갯수 확인 테이블\\n(\\n\\tWorldID\\t\\tINT,\\n\\tTemplateID \\tINT,\\n\\tITEM_COUNT_TYPE\\tINT,\\n\\tITEM_COUNT_TOTAL\\tINT\\n)\\n\\nDROP TABLE IF EXISTS ##__D_TargetItem;\\nCREATE TABLE ##__D_TargetItem\\n(\\n\\tTemplateID\\tINT,\\n)\\n\\nINSERT INTO ##__D_TargetItem VALUES --삭제 아이템\\n(12349);\\n-- ! 실제 아이템을 입력하는 부분에서 replace 토큰으로 수정이 필요합니다.\\n\\nBEGIN TRAN\\nBEGIN TRY\\n\\n\\tDECLARE @IsCommit\\t\\t\\t\\tINT = 1; --저장 여부\\n\\tDECLARE @IsClearTempTable\\t\\tINT = 1; --임시 테이블 삭제 여부\\n\\t\\t\\n\\tDECLARE @DQ_CHECKCOUNT \\t\\t\\tNVARCHAR(MAX) = \'\';\\n\\tDECLARE @DQ_CHECKCOUNT_P\\t\\tNVARCHAR(MAX) = \'@TypeWeb\\tINT,\\n\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t @TypeInv\\tINT\';\\n\\tDECLARE @DQ_CHECKCOUNT_P_WebBEF\\tINT = 0; --Web 쿼리 적용 전\\n\\tDECLARE @DQ_CHECKCOUNT_P_InvBEF\\tINT = 2; --Inv 쿼리 적용 전\\n\\tDECLARE @DQ_CHECKCOUNT_P_WebAFT\\tINT = 1; --Web 쿼리 적용 후\\n\\tDECLARE @DQ_CHECKCOUNT_P_InvAFT\\tINT = 3; --Inv 쿼리 적용 후\\n\\tDECLARE @DQ_D_WAITCASH \\t\\t\\tNVARCHAR(MAX) = \'\';\\n\\tDECLARE @DQ_D_INV\\t \\t\\t\\tNVARCHAR(MAX) = \'\';\\n\\n\\t-- 쿼리 적용 전 해당 아이템의 갯수\\n\\tSELECT @DQ_CHECKCOUNT = CONCAT(@DQ_CHECKCOUNT, \'\\n\\t\\t\\tINSERT INTO ##__UserCheck(WorldID, TemplateID, ITEM_COUNT_TYPE, ITEM_COUNT_TOTAL)\\n\\t\\t\\t\\tSELECT \', TargetW.WorldID, \', TI.TemplateID\\n\\t\\t\\t\\t\\t\\t, @TypeWeb\\n\\t\\t\\t\\t\\t\\t, (SELECT ISNULL(SUM(WCI.Count), 0) FROM \', TargetW.ServerName, \'.dbo.WaitWebCashItem WCI WHERE WCI.ItemTemplateID = TI.TemplateID)\\n\\t\\t\\t\\tFROM ##__D_TargetItem TI;\\t\\t\\n\\t\\t\\tINSERT INTO ##__UserCheck(WorldID, TemplateID, ITEM_COUNT_TYPE, ITEM_COUNT_TOTAL)\\n\\t\\t\\t\\tSELECT \', TargetW.WorldID, \', TI.TemplateID\\n\\t\\t\\t\\t\\t\\t, @TypeInv\\n\\t\\t\\t\\t\\t\\t, (SELECT ISNULL(SUM(INV.Count), 0) FROM \', TargetW.ServerName, \'.dbo.Inventory INV WHERE INV.ItemTemplateID = TI.TemplateID AND INV.ItemState = 1)\\n\\t\\t\\t\\tFROM ##__D_TargetItem TI\')\\n\\tFROM ##__TargetWorld TargetW\\n\\t\\n\\tEXEC SP_EXECUTESQL @DQ_CHECKCOUNT, @DQ_CHECKCOUNT_P, @TypeWeb = @DQ_CHECKCOUNT_P_WebBEF, @TypeInv = @DQ_CHECKCOUNT_P_InvBEF;\\n\\t\\t\\n\\t--아이템 삭제 쿼리\\n\\tSELECT @DQ_D_WAITCASH = CONCAT(@DQ_D_WAITCASH, \'\\n\\t\\t\\tDELETE \', TargetW.ServerName, \'.dbo.WaitWebCashItem \\n\\t\\t\\tWHERE ItemTemplateID IN (SELECT TemplateID FROM ##__D_TargetItem TI)\')\\n\\tFROM ##__TargetWorld TargetW\\n\\t\\n\\tSELECT @DQ_D_INV = CONCAT(@DQ_D_INV, \'\\n\\t\\t\\tUPDATE \', TargetW.ServerName, \'.dbo.Inventory\\n\\t\\t\\tSET ItemState = 2\\n\\t\\t\\tWHERE ItemTemplateID IN (SELECT TemplateID FROM ##__D_TargetItem TI)\')\\n\\tFROM ##__TargetWorld TargetW\\n\\t\\t\\n\\tEXEC SP_EXECUTESQL @DQ_D_WAITCASH;\\n\\tEXEC SP_EXECUTESQL @DQ_D_INV;\\n\\t\\n\\t-- 쿼리 적용 후 해당 아이템 갯수\\n\\tEXEC SP_EXECUTESQL @DQ_CHECKCOUNT, @DQ_CHECKCOUNT_P, @TypeWeb = @DQ_CHECKCOUNT_P_WebAFT, @TypeInv = @DQ_CHECKCOUNT_P_InvAFT;\\n\\n\\tSELECT PIV.WorldID, PIV.TemplateID, ITM.Name, PIV.[0] AS BeforeWebItemCount, PIV.[1] AS AfterWebItemCount, PIV.[2] AS BeforeInvItemCount, PIV.[3] AS AfterInvItemCount\\n\\tFROM(SELECT *\\n\\t\\t\\tFROM ##__UserCheck As res\\n\\t\\t\\tPIVOT (SUM(ITEM_COUNT_TOTAL) FOR ITEM_COUNT_TYPE IN ([0], [1], [2], [3])) as pi\\n\\t\\t) PIV\\n\\tLEFT JOIN dk_data_release.dbo.Item AS ITM ON ITM.TemplateID = PIV.TemplateID\\n\\tORDER BY PIV.WorldID, PIV.TemplateID\\n\\n\\tIF(@IsCommit = 1)\\n\\tBEGIN\\n\\t\\tCOMMIT TRAN\\n\\tEND\\n\\tELSE\\n\\tBEGIN\\n\\t\\tSELECT \'ROLLBACK\'\\n\\t\\tROLLBACK TRAN\\n\\tEND\\n\\t\\nEND TRY\\nBEGIN CATCH\\n\\tSELECT \'ERROR\', ERROR_MESSAGE()\\n\\tROLLBACK TRAN\\nEND CATCH\\n\\nIF(@IsClearTempTable = 1)\\nBEGIN\\n\\tDROP TABLE IF EXISTS ##__TargetWorld;\\n\\tDROP TABLE IF EXISTS ##__UserCheck; \\n\\tDROP TABLE IF EXISTS ##__D_TargetItem;\\nEND\\n\\nGo", "nSetIndex": 0, "strBefore": "--아이템 삭제 쿼리\\n--전부 삭제\\n-- 적용 일자 : 2026-01-08\\n/*\\n--특정 서버만 적용할때 사용\\nDROP TABLE IF EXISTS ##__TargetWorld;\\nSELECT WorldID, ServerName\\n\\tINTO ##__TargetWorld\\nFROM dk_game_integrate.dbo.ConnectInfo\\nWHERE WorldID IN  -- 적용할 서버\\n\\t(\\n\\t\\t224\\n\\t  , 234\\n\\t  , 235\\n\\t  , 236\\n\\t  , 237\\n\\t  , 238\\n\\t  , 239\\n\\t  , 240\\n\\t)\\nORDER BY WorldID\\n*/\\n\\n--통합된 서버에 전부 적용할때 사용\\nDROP TABLE IF EXISTS ##__TargetWorld;\\nSELECT WorldID, ServerName\\n\\tINTO ##__TargetWorld\\nFROM dk_game_integrate.dbo.ConnectInfo\\nWHERE ServerGroupID IN  -- 적용할 서버 그룹\\n\\t(\\n\\t\\t50, 53\\n\\t)\\nORDER BY WorldID\\n\\nDROP TABLE IF EXISTS ##__UserCheck; \\nCREATE TABLE ##__UserCheck --갯수 확인 테이블\\n(\\n\\tWorldID\\t\\tINT,\\n\\tTemplateID \\tINT,\\n\\tITEM_COUNT_TYPE\\tINT,\\n\\tITEM_COUNT_TOTAL\\tINT\\n)\\n\\nDROP TABLE IF EXISTS ##__D_TargetItem;\\nCREATE TABLE ##__D_TargetItem\\n(\\n\\tTe