	(5, 2, 'DK온라인', '[DK/G] 퀘스트 일괄 삭제', '2026년 7월 21일 퀘스트 일괄 삭제입니다.', '퀘스트', '삭제', 'item_number', NULL, NULL, '기획-심현우', 2, '2026-07-09 18:04:03.771000', 'template_created', '[{"strStatus": "template_created", "strComment": "쿼리 템플릿 등록", "dtChangedAt": "2026-07-09T09:04:03.771Z", "strChangedBy": "기획-심현우", "nChangedByUserId": 2}]', '{"nUserId": 2, "strUserId": "hwshim", "dtProcessedAt": "2026-07-09T09:04:03.771Z", "strDisplayName": "기획-심현우"}', NULL),
	(6, 4, '아스다글로벌', '젬 소비 누적 초기화', '기존 PayBackEvent 테이블을 백업하고 초기화 수행', '아이템', '초기화', 'item_string', NULL, NULL, '김민규', 6, '2026-07-14 13:44:11.689000', 'dba_confirmed', '[{"strStatus": "template_created", "strComment": "쿼리 템플릿 등록", "dtChangedAt": "2026-07-14T04:44:11.689Z", "strChangedBy": "김민규", "nChangedByUserId": 6}, {"strStatus": "confirm_requested", "strComment": "", "dtChangedAt": "2026-07-14T04:44:50.268Z", "strChangedBy": "김민규", "nChangedByUserId": 6}, {"strStatus": "confirm_requested", "strComment": "DBA 쿼리 리뷰 중 수정", "dtChangedAt": "2026-07-14T04:46:15.484Z", "objQueryEdit": {"arrSetChanges": [{"strAfter": "/*  ​\\n점검 일정: 2026.07.21 (화) 오후 15:00\\n ​\\n 07/21 점검 시 젬 소비 이벤트 누적 데이터의 초기화가 필요하여 요청드립니다.\\n ​\\n 잘 부탁드립니다!\\n*/\\nUSE Joy1\\nGO\\n\\nBEGIN TRANSACTION\\n\\nDECLARE @ExecuteDate NVARCHAR(16) = {{date}};\\nDECLARE @IsCommit TINYINT = 0;\\t\\t/*** 라이브 적용 시 값 변경 부탁드립니다 : [1] ***/\\n\\n-- 백업 쿼리 실행\\nDECLARE @DQ_BackupTable NVARCHAR(MAX) = CONCAT( \'\\nIF EXISTS(SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME=\'\'PayBackEvent_\', @ExecuteDate, \'\'\')\\n\\tDROP Table dbo.PayBackEvent_\', @ExecuteDate, \';\\nSELECT * INTO dbo.PayBackEvent_\', @ExecuteDate, \' FROM dbo.PayBackEvent WITH (TABLOCK)\\n\' );\\nEXEC sp_ExecuteSql @DQ_BackupTable;\\n\\nSELECT * FROM Joy1.dbo.PayBackEvent;\\n\\nBEGIN TRY\\nDELETE FROM Joy1.dbo.PayBackEvent ;\\nEND TRY\\nBEGIN CATCH\\nIF @@ERROR <> 0\\nBEGIN\\n\\tROLLBACK TRANSACTION\\n\\tRETURN\\nEND\\nEND CATCH\\n\\nSELECT * FROM Joy1.dbo.PayBackEvent\\n\\nIF (1 = @IsCommit)\\nBEGIN\\n\\tSELECT \'Run complete\' AS \'Do : COMMIT\';\\n\\tCOMMIT TRANSACTION\\nEND\\nELSE\\nBEGIN\\n\\tSELECT IIF( @IsCommit = 1, \'Error on delete\', \'Commit canceled ( @IsCommit = 0 )\') AS \'Do : ROLLBACK\';\\n\\tROLLBACK TRANSACTION\\nEND", "nSetIndex": 0, "strBefore": "/*  ​\\n점검 일정: 2026.07.21 (화) 오후 15:00\\n ​\\n 06/23 점검 시 젬 소비 이벤트 누적 데이터의 초기화가 필요하여 요청드립니다.  ​  ​\\n 07/21 점검 시 젬 소비 이벤트 누적 데이터의 초기화가 필요하여 요청드립니다.\\n ​\\n 잘 부탁드립니다!\\n*/\\nUSE Joy1\\nGO\\n\\nBEGIN TRANSACTION\\n\\nDECLARE @ExecuteDate NVARCHAR(16) = {{date}};\\nDECLARE @IsCommit TINYINT = 0;\\t\\t/*** 라이브 적용 시 값 변경 부탁드립니다 : [1] ***/\\n\\n-- 백업 쿼리 실행\\nDECLARE @DQ_BackupTable NVARCHAR(MAX) = CONCAT( \'\\nIF EXISTS(SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME=\'\'PayBackEvent_\', @ExecuteDate, \'\'\')\\n\\tDROP Table dbo.PayBackEvent_\', @ExecuteDate, \';\\nSELECT * INTO dbo.PayBackEvent_\', @ExecuteDate, \' FROM dbo.PayBackEvent WITH (TABLOCK)\\n\' );\\nEXEC sp_ExecuteSql @DQ_BackupTable;\\n\\nSELECT * FROM Joy1.dbo.PayBackEvent;\\n\\nBEGIN TRY\\nDELETE FROM Joy1.dbo.PayBackEvent ;\\nEND TRY\\nBEGIN CATCH\\nIF @@ERROR <> 0\\nBEGIN\\n\\tROLLBACK TRANSACTION\\n\\tRETURN\\nEND\\nEND CATCH\\n\\nSELECT * FROM Joy1.dbo.PayBackEvent\\n\\nIF (1 = @IsCommit)\\nBEGIN\\n\\tSELECT \'Run complete\' AS \'Do : COMMIT\';\\n\\tCOMMIT TRANSACTION\\nEND\\nELSE\\nBEGIN\\n\\tSELECT IIF( @IsCommit = 1, \'Error on delete\', \'Commit canceled ( @IsCommit = 0 )\') AS \'Do : ROLLBACK\';\\n\\tROLLBACK TRANSACTION\\nEND"}]}, "strChangedBy": "김민규", "nChangedByUserId": 6}, {"strStatus": "confirm_requested", "strComment": "DBA 쿼리 리뷰 중 수정", "dtChangedAt": "2026-07-14T05:54:03.160Z", "objQueryEdit": {"arrSetChanges": [{"strAfter": "/*  ​\\n점검 일정: 2026.07.21 (화) 오후 15:00\\n ​\\n 07/21 점검 시 젬 소비 이벤트 누적 데이터의 초기화가 필요하여 요청드립니다.\\n ​\\n 잘 부탁드립니다!\\n*/\\nUSE Joy1\\n\\nBEGIN TRANSACTION\\n\\nDECLARE @ExecuteDate NVARCHAR(16) = {{date}};\\nDECLARE @IsCommit TINYINT = 0;\\t\\t/*** 라이브 적용 시 값 변경 부탁드립니다 : [1] ***/\\n\\n-- 백업 쿼리 실행\\nDECLARE @DQ_BackupTable NVARCHAR(MAX) = CONCAT( \'\\nIF EXISTS(SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME=\'\'PayBackEvent_\', @ExecuteDate, \'\'\')\\n\\tDROP Table dbo.PayBackEvent_\', @ExecuteDate, \';\\nSELECT * INTO dbo.PayBackEvent_\', @ExecuteDate, \' FROM dbo.PayBackEvent WITH (TABLOCK)\\n\' );\\nEXEC sp_ExecuteSql @DQ_BackupTable;\\n\\nSELECT * FROM Joy1.dbo.PayBackEvent;\\n\\nBEGIN TRY\\nDELETE FROM Joy1.dbo.PayBackEvent ;\\nEND TRY\\nBEGIN CATCH\\nIF @@ERROR <> 0\\nBEGIN\\n\\tROLLBACK TRANSACTION\\n\\tRETURN\\nEND\\nEND CATCH\\n\\nSELECT * FROM Joy1.dbo.PayBackEvent\\n\\nIF (1 = @IsCommit)\\nBEGIN\\n\\tSELECT \'Run complete\' AS \'Do : COMMIT\';\\n\\tCOMMIT TRANSACTION\\nEND\\nELSE\\nBEGIN\\n\\tSELECT IIF( @IsCommit = 1, \'Error on delete\', \'Commit canceled ( @IsCommit = 0 )\') AS \'Do : ROLLBACK\';\\n\\tROLLBACK TRANSACTION\\nEND", "nSetIndex": 0, "strBefore": "/*  ​\\n점검 일정: 2026.07.21 (화) 오후 15:00\\n ​\\n 07/21 점검 시 젬 소비 이벤트 누적 데이터의 초기화가 필요하여 요청드립니다.\\n ​\\n 잘 부탁드립니다!\\n*/\\nUSE Joy1\\nGO\\n\\nBEGIN TRANSACTION\\n\\nDECLARE @ExecuteDate NVARCHAR(16) = {{date}};\\nDECLARE @IsCommit TINYINT = 0;\\t\\t/*** 라이브 적용 시 값 변경 부탁드립니다 : [1] ***/\\n\\n-- 백업 쿼리 실행\\nDECLARE @DQ_BackupTable NVARCHAR(MAX) = CONCAT( \'\\nIF EXISTS(SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME=\'\'PayBackEvent_\', @ExecuteDate, \'\'\')\\n\\tDROP Table dbo.PayBackEvent_\', @ExecuteDate, \';\\nSELECT * INTO dbo.PayBackEvent_\', @ExecuteDate, \' FROM dbo.PayBackEvent WITH (TABLOCK)\\n\' );\\nEXEC sp_ExecuteSql @DQ_BackupTable;\\n\\nSELECT * FROM Joy1.dbo.PayBackEvent;\\n\\nBEGIN TRY\\nDELETE FROM Joy1.dbo.PayBackEvent ;\\nEND TRY\\nBEGIN CATCH\\nIF @@ERROR <> 0\\nBEGIN\\n\\tROLLBACK TRANSACTION\\n\\tRETURN\\nEND\\nEND CATCH\\n\\nSELECT * FROM Joy1.dbo.PayBackEvent\\n\\nIF (1 = @IsCommit)\\nBEGIN\\n\\tSELECT \'Run complete\' AS \'Do : COMMIT\';\\n\\tCOMMIT TRANSACTION\\nEND\\nELSE\\nBEGIN\\n\\tSELECT IIF( @IsCommit = 1, \'Error on delete\', \'Commit canceled ( @IsCommit = 0 )\') AS \'Do : ROLLBACK\';\\n\\tROLLBACK TRANSACTION\\nEND"}]}, "strChangedBy": "김민철", "nChangedByUserId": 5}, {"strStatus": "dba_confirmed", "strComment": "", "dtChangedAt": "2026-07-16T01:40:20.064Z", "strChangedBy": "김민철", "nChangedByUserId": 5}]', '{"nUserId": 6, "strUserId": "mgkim2", "dtProcessedAt": "2026-07-14T04:44:11.689Z", "strDisplayName": "김민규"}', '{"nUserId": 5, "strUserId": "mckim", "dtProcessedAt": "2026-07-16T01:40:20.064Z", "strDisplayName": "김민철"}'),
	(7, 8, '건즈온라인', '출석 초기화', '출석 체크를 초기화하는 쿼리', '퀘스트', '초기화', 'item_number', NULL, NULL, '박필규', 14, '2026-07-22 14:29:40.044000', 'dba_confirmed', '[{"strStatus": "template_created", "strComment": "쿼리 템플릿 등록", "dtChangedAt": "2026-07-22T05:29:40.044Z", "strChangedBy": "박필규", "nChangedByUserId": 14}, {"strStatus": "confirm_requested", "strComment": "", "dtChangedAt": "2026-07-22T05:30:47.242Z", "strChangedBy": "박필규", "nChangedByUserId": 14}, {"strStatus": "dba_confirmed", "strComment": "", "dtChangedAt": "2026-07-22T05:34:12.136Z", "strChangedBy": "김민철", "nChangedByUserId": 5}]', '{"nUserId": 14, "strUserId": "pgpark", "dtProcessedAt": "2026-07-22T05:29:40.044Z", "strDisplayName": "박필규"}', '{"nUserId": 5, "strUserId": "mckim", "dtProcessedAt": "2026-07-22T05:34:12.136Z", "strDisplayName": "김민철"}');
INSERT INTO `event_template_query_set` (`n_id`, `n_event_template_id`, `n_sort`, `n_db_connection_id`, `n_live_db_connection_id`, `str_input_id`, `str_input_format`, `str_default_items`, `str_query_template`) VALUES
	(300, 1, 0, 1, 2, 'items', 'item_number', '123,456,789', 'INSERT INTO dual VALUES ({{items}}) as \'col2\';'),
	(301, 1, 1, 1, 2, 'items', 'item_number', '123', 'select {{items}} as \'col1\';'),
	(302, 2, 0, 5, 6, 'items', 'item_number', '1,2,3', '--아이템 삭제 준비\n\n/*\n점검 일정: 2026.07.07 (화) 15:00\n​\n점검시 전월 이벤트 아이템 삭제가 필요하여 요청드립니다.\n해당 아이템들은 아래와 같습니다.\n\n81259	^[E]Blue Candle^\n81260	^[E]Green Candle^\n81261	^[E]Yellow Candle^\n81262	^[E]Red Candle^\n80921	^[E]Celebration Coin^\n\n잘 부탁드립니다!\n\n+ 2023.12.08\n	- 삭제된 행 수가 동일하면 커밋하도록 수정하였습니다.\n	- @IsCommit 변수가 1 일 경우 커밋하도록 수정하였습니다.\n*/\n\nUSE [Joy1]\n\nBEGIN TRANSACTION\n\nDECLARE @IsCommit TINYINT = 0;		/*** 라이브 적용 시 값 변경 부탁드립니다 : [1] ***/\nDECLARE @IsPrintQuery TINYINT = 0;\n\nDECLARE @InputString NVARCHAR(1000) = \'{{items}}\';\n\nDECLARE @TODAY NVARCHAR(20) = CONVERT(VARCHAR(8), getdate(), 112)\nDECLARE @MyTempTable TABLE (MyItemIndex INT)\nDECLARE @Value INT, @pos INT\n\n-- 제거 아이템\nIF EXISTS( SELECT TABLE_NAME FROM tempdb.INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME LIKE \'%DeleteItem\' )\n	DROP TABLE ##DeleteItem\nCREATE TABLE ##DeleteItem (\n	MyItemIndex	INT\n)\n\n-- 대상 테이블\nIF EXISTS( SELECT TABLE_NAME FROM tempdb.INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME LIKE \'%TargetTable\' )\n	DROP TABLE ##TargetTable\nCREATE TABLE ##TargetTable (\n	TableName		NVARCHAR(64)		-- 테이블 명칭\n,	IsBackup		TINYINT				-- 백업 여부		( 0 / 1 )\n,	IsClear			TINYINT				-- 아이템 제거 여부	( 0 / 1 )\n,	SourceItemCount	BIGINT	DEFAULT(0)	-- 삭제 전 아이템 개수\n,	DeleteItemCount BIGINT	DEFAULT(0)	-- 삭제된 아이템 개수\n)\n\nWHILE CHARINDEX(\',\', @InputString) <> 0\nBEGIN\n	SET @pos = CHARINDEX(\',\', @InputString)\n	SET @Value = CAST(SUBSTRING(@InputString, 1, @pos-1) AS INT)\n	INSERT INTO ##DeleteItem(MyItemIndex) VALUES(@Value)\n	SET @InputString = SUBSTRING(@InputString, @pos+1, LEN(@InputString)-@pos)\nEND\nSET @Value = CAST(SUBSTRING(@InputString, 1, LEN(@InputString)) AS INT)\nINSERT INTO ##DeleteItem(MyItemIndex) VALUES(@Value)\n\nINSERT INTO ##TargetTable(IsBackup, IsClear, TableName) VALUES \n	(1, 1, \'Item\')				-- 인벤&창고\n,	(1, 1, \'Exitem\')			-- 거래소\n,	(1, 1, \'ItemPostbox\')		-- 우편함\n,	(1, 0, \'PostExpress\')		-- 개인우편함 : 아이템 제거사항 없음\n,	(1, 1, \'PostExpressItem\')	-- 개인우편함아이템\n\n--- 테이블 백업 ---\nDECLARE @DQuery_Backup NVARCHAR(MAX) = \'\';\nSELECT @DQuery_Backup = CONCAT( @DQuery_Backup, \'\n	IF EXISTS( SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME = \'\'\', TableName, \'_\', @TODAY,\'\'\')\n		DROP TABLE dbo.\', TableName,\'_\', @TODAY, \'\n	SELECT * INTO dbo.\', TableName,\'_\', @TODAY, \' FROM \', TableName, \' WITH (TABLOCK)\n	\')\n	FROM ##TargetTable\n		WHERE IsBackup = 1;\n\nIF(@IsPrintQuery = 1) PRINT @DQuery_Backup\nEXEC sp_ExecuteSql @DQuery_Backup;\n\n--- 조회 시작 ---\nDECLARE @DQuery_SaveSourceItemCount NVARCHAR(MAX) = \'\';\nSELECT @DQuery_SaveSourceItemCount = CONCAT( @DQuery_SaveSourceItemCount, \'\n	UPDATE ##TargetTable SET\n		SourceItemCount = [_CurTable].ItemCount\n	FROM ( SELECT COUNT(*) AS [ItemCount]\n			FROM \', TableName, \' \n				WHERE Code IN ( SELECT MyItemIndex FROM ##DeleteItem ) ) AS [_CurTable]\n		WHERE TableName = \'\'\', TableName, \'\'\'\n	\')\n	FROM ##TargetTable\n		WHERE IsClear = 1;\n		\nIF(@IsPrintQuery = 1) PRINT @DQuery_SaveSourceItemCount\nEXEC sp_ExecuteSql @DQuery_SaveSourceItemCount;\n\n--- 삭제 시작 ---\nBEGIN TRY\n\nDECLARE @DQuery_DeleteItem NVARCHAR(MAX) = \'\';\nSELECT @DQuery_DeleteItem = CONCAT( @DQuery_DeleteItem, \'\n	DELETE FROM \', TableName, \'\n		WHERE Code IN ( SELECT MyItemIndex FROM ##DeleteItem )\n\n	-- 삭제된 아이템 개수 입력\n	UPDATE ##TargetTable SET\n		DeleteItemCount = @@ROWCOUNT\n	WHERE TableName = \'\'\', TableName, \'\'\'\n	\')\n	FROM ##TargetTable\n		WHERE IsClear = 1;\n\nIF(@IsPrintQuery = 1) PRINT @DQuery_DeleteItem\nEXEC sp_ExecuteSql @DQuery_DeleteItem;\n\n-- 개인 우편함은 별도 처리\nUPDATE postExpress SET Itemorder=-1 WHERE ItemOrder IN (SELECT Orderidx FROM dbo.PostExpressItem WITH(NOLOCK) \nWHERE code IN (SELECT MyItemIndex FROM ##DeleteItem))\n\nEND TRY\nBEGIN CATCH\n\nIF @@ERROR <> 0\nBEGIN\n	PRINT \'** Error on delete **\'\n	ROLLBACK TRANSACTION\n	RETURN\nEND\nEND CATCH\n--삭제 작업 종료-\n\n-- 삭제 결과 출력\nSELECT	TableName\n	,	SourceItemCount AS \'기존 아이템 개수\'\n	,	DeleteItemCount AS \'삭제된 아이템 개수\'\n	FROM ##TargetTable\n		WHERE IsClear = 1\n\n-- 조회와 삭제 결과가 동일한지 비교\nDECLARE @IsComplate TINYINT = 1;\nSELECT @IsComplate = 0\n	FROM ##TargetTable\n		WHERE	IsClear = 1\n			AND SourceItemCount != DeleteItemCount\n\n-- 임시 테이블 제거\nIF EXISTS( SELECT TABLE_NAME FROM tempdb.INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME LIKE \'%DeleteItem\' )\n	DROP TABLE ##DeleteItem\nIF EXISTS( SELECT TABLE_NAME FROM tempdb.INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME LIKE \'%TargetTable\' )\n	DROP TABLE ##TargetTable	\n\n-- 조회 결과가 정상적이라면 커밋\nIF( @IsComplate = 1 AND @IsCommit = 1 )\nBEGIN\n	SELECT \'Run complate\' AS \'Do : COMMIT\';\n	COMMIT TRANSACTION\nEND\nELSE\nBEGIN\n	SELECT IIF( @IsCommit = 1, \'Error on delete\', \'Commit canceled ( @IsCommit = 0 )\') AS \'Do : ROLLBACK\';\n	ROLLBACK TRANSACTION\nEND'),
	(303, 3, 0, 13, 14, 'items', 'item_number', '12349,4,5', '--아이템 삭제 쿼리\n--전부 삭제\n-- 적용 일자 : 2026-01-08\n/*\n--특정 서버만 적용할때 사용\nDROP TABLE IF EXISTS ##__TargetWorld;\nSELECT WorldID, ServerName\n	INTO ##__TargetWorld\nFROM dk_game_integrate.dbo.ConnectInfo\nWHERE WorldID IN  -- 적용할 서버\n	(\n		224\n	  , 234\n	  , 235\n	  , 236\n	  , 237\n	  , 238\n	  , 239\n	  , 240\n	)\nORDER BY WorldID\n*/\n\n--통합된 서버에 전부 적용할때 사용\nDROP TABLE IF EXISTS ##__TargetWorld;\nSELECT WorldID, ServerName\n	INTO ##__TargetWorld\nFROM dk_game_integrate.dbo.ConnectInfo\nWHERE ServerGroupID IN  -- 적용할 서버 그룹\n	(\n		50, 53\n	)\nORDER BY WorldID\n\nDROP TABLE IF EXISTS ##__UserCheck; \nCREATE TABLE ##__UserCheck --갯수 확인 테이블\n(\n	WorldID		INT,\n	TemplateID 	INT,\n	ITEM_COUNT_TYPE	INT,\n	ITEM_COUNT_TOTAL	INT\n)\n\nDROP TABLE IF EXISTS ##__D_TargetItem;\nCREATE TABLE ##__D_TargetItem\n(\n	TemplateID	INT,\n)\n\nINSERT INTO ##__D_TargetItem VALUES --삭제 아이템\n{{items}};\n-- ! 실제 아이템을 입력하는 부분에서 replace 토큰으로 수정이 필요합니다.\n\nBEGIN TRAN\nBEGIN TRY\n\n	DECLARE @IsCommit				INT = 1; --저장 여부\n	DECLARE @IsClearTempTable		INT = 1; --임시 테이블 삭제 여부\n		\n	DECLARE @DQ_CHECKCOUNT 			NVARCHAR(MAX) = \'\';\n	DECLARE @DQ_CHECKCOUNT_P		NVARCHAR(MAX) = \'@TypeWeb	INT,\n													 @TypeInv	INT\';\n	DECLARE @DQ_CHECKCOUNT_P_WebBEF	INT = 0; --Web 쿼리 적용 전\n	DECLARE @DQ_CHECKCOUNT_P_InvBEF	INT = 2; --Inv 쿼리 적용 전\n	DECLARE @DQ_CHECKCOUNT_P_WebAFT	INT = 1; --Web 쿼리 적용 후\n	DECLARE @DQ_CHECKCOUNT_P_InvAFT	INT = 3; --Inv 쿼리 적용 후\n	DECLARE @DQ_D_WAITCASH 			NVARCHAR(MAX) = \'\';\n	DECLARE @DQ_D_INV	 			NVARCHAR(MAX) = \'\';\n\n	-- 쿼리 적용 전 해당 아이템의 갯수\n	SELECT @DQ_CHECKCOUNT = CONCAT(@DQ_CHECKCOUNT, \'\n			INSERT INTO ##__UserCheck(WorldID, TemplateID, ITEM_COUNT_TYPE, ITEM_COUNT_TOTAL)\n				SELECT \', TargetW.WorldID, \', TI.TemplateID\n						, @TypeWeb\n						, (SELECT ISNULL(SUM(WCI.Count), 0) FROM \', TargetW.ServerName, \'.dbo.WaitWebCashItem WCI WHERE WCI.ItemTemplateID = TI.TemplateID)\n				FROM ##__D_TargetItem TI;		\n			INSERT INTO ##__UserCheck(WorldID, TemplateID, ITEM_COUNT_TYPE, ITEM_COUNT_TOTAL)\n				SELECT \', TargetW.WorldID, \', TI.TemplateID\n						, @TypeInv\n						, (SELECT ISNULL(SUM(INV.Count), 0) FROM \', TargetW.ServerName, \'.dbo.Inventory INV WHERE INV.ItemTemplateID = TI.TemplateID AND INV.ItemState = 1)\n				FROM ##__D_TargetItem TI\')\n	FROM ##__TargetWorld TargetW\n	\n	EXEC SP_EXECUTESQL @DQ_CHECKCOUNT, @DQ_CHECKCOUNT_P, @TypeWeb = @DQ_CHECKCOUNT_P_WebBEF, @TypeInv = @DQ_CHECKCOUNT_P_InvBEF;\n		\n	--아이템 삭제 쿼리\n	SELECT @DQ_D_WAITCASH = CONCAT(@DQ_D_WAITCASH, \'\n			DELETE \', TargetW.ServerName, \'.dbo.WaitWebCashItem \n			WHERE ItemTemplateID IN (SELECT TemplateID FROM ##__D_TargetItem TI)\')\n	FROM ##__TargetWorld TargetW\n	\n	SELECT @DQ_D_INV = CONCAT(@DQ_D_INV, \'\n			UPDATE \', TargetW.ServerName, \'.dbo.Inventory\n			SET ItemState = 2\n			WHERE ItemTemplateID IN (SELECT TemplateID FROM ##__D_TargetItem TI)\')\n	FROM ##__TargetWorld TargetW\n		\n	EXEC SP_EXECUTESQL @DQ_D_WAITCASH;\n	EXEC SP_EXECUTESQL @DQ_D_INV;\n	\n	-- 쿼리 적용 후 해당 아이템 갯수\n	EXEC SP_EXECUTESQL @DQ_CHECKCOUNT, @DQ_CHECKCOUNT_P, @TypeWeb = @DQ_CHECKCOUNT_P_WebAFT, @TypeInv = @DQ_CHECKCOUNT_P_InvAFT;\n\n	SELECT PIV.WorldID, PIV.TemplateID, ITM.Name, PIV.[0] AS BeforeWebItemCount, PIV.[1] AS AfterWebItemCount, PIV.[2] AS BeforeInvItemCount, PIV.[3] AS AfterInvItemCount\n	FROM(SELECT *\n			FROM ##__UserCheck As res\n			PIVOT (SUM(ITEM_COUNT_TOTAL) FOR ITEM_COUNT_TYPE IN ([0], [1], [2], [3])) as pi\n		) PIV\n	LEFT JOIN dk_data_release.dbo.Item AS ITM ON ITM.TemplateID = PIV.TemplateID\n	ORDER BY PIV.WorldID, PIV.TemplateID\n\n	IF(@IsCommit = 1)\n	BEGIN\n		COMMIT TRAN\n	END\n	ELSE\n	BEGIN\n		SELECT \'ROLLBACK\'\n		ROLLBACK TRAN\n	END\n	\nEND TRY\nBEGIN CATCH\n	SELECT \'ERROR\', ERROR_MESSAGE()\n	ROLLBACK TRAN\nEND CATCH\n\nIF(@IsClearTempTable = 1)\nBEGIN\n	DROP TABLE IF EXISTS ##__TargetWorld;\n	DROP TABLE IF EXISTS ##__UserCheck; \n	DROP TABLE IF EXISTS ##__D_TargetItem;\nEND\n\nGo'),
	(304, 4, 0, 13, 14, 'items', 'item_number', '521002249, 521002250, 521002251', 'USE master;\nGO\n/*\n\n서버명 : 전서버 대상\n\nQuestState\n- 1 : 진행\n- 2 : 완료\n- 3 : 포기\n*/\n\n-- [설정 : 적용 여부]\nDECLARE @IsCommit TINYINT = 1;\nDECLARE @IsDebug TINYINT = 0;\n\n-- [설정 : 대상 ID]\nDROP TABLE IF EXISTS ##TargetItem;\nCREATE TABLE ##TargetItem (\n	RowNum		INT IDENTITY(1, 1)		PRIMARY KEY\n,	TargetID	INT		-- ** 탐색할 ID 타입에 따라 변경 **\n);\nINSERT INTO ##TargetItem ( TargetID ) VALUES\n{{items}}\n-- ! 실제 아이템을 입력하는 부분에서 replace 토큰으로 수정이 필요합니다.\n\n-- [설정 : 대상 DB]\nDROP TABLE IF EXISTS ##TargetDB;\nCREATE TABLE ##TargetDB (\n	RowNum		INT IDENTITY(1, 1)		PRIMARY KEY\n,	TargetDB	VARCHAR(32)\n);\nINSERT INTO ##TargetDB (TargetDB) \nSELECT ServerName\n	FROM dk_game_integrate.dbo.ConnectInfo\n		WHERE	ServerGroupID IN ( 50, 53 )	-- 적용할 서버 그룹\n			AND	DB_ID( ServerName ) IS NOT NULL\n		ORDER BY WorldID\n\n-- [설정 : 대상 테이블, 탐색 양식]\nDROP TABLE IF EXISTS ##TargetTable;\nCREATE TABLE ##TargetTable (\n	RowNum			INT IDENTITY(1, 1)	PRIMARY KEY\n,	TableName		NVARCHAR(64)\n,	TargetColumn	NVARCHAR(64)\n,	FormatProcess	NVARCHAR(MAX)		-- {C}:[TargetColumn], {I}:TargetIDs, {T}:[TableName], {W}:[FormatWhere]\n,	FormatWhere		NVARCHAR(MAX)		-- {C}:[TargetColumn], {I}:TargetIDs, {T}:[TableName]\n,	Separator		VARCHAR(MAX)		-- {C}:[TargetColumn]\n);\n\nINSERT INTO ##TargetTable\n(	TableName, TargetColumn	-- 대상 테이블, 컬럼 명칭\n,	FormatProcess			-- 일괄 적용될 쿼리 양식\n,	FormatWhere				-- 조회, 적용 조건\n,	Separator				-- 구분자 (필요할 경우에만 입력)\n)\nVALUES\n(	\'Quest\', \'QuestID\'\n,	\'UPDATE {T} SET QuestState = 3 WHERE {W}\'\n,	\'{C} IN ( SELECT TargetID FROM ##TargetItem ) AND QuestState != 3\'\n,	NULL )\n--,(	\'SKID_ITEM_TB\', \'ITEMID\'\n--,	\'DELETE FROM {T} WHERE {W}\'\n--,	\'{C} LIKE \'\'{I}\'\'\'\n--,	\'\'\' OR {C} LIKE \'\'\' )\n;\n\n-- 쿼리 작성 : 구분자\nDECLARE @IsForcedSep TINYINT = IIF(EXISTS(SELECT TOP(1) * FROM ##TargetTable WHERE Separator IS NOT NULL), 0, 1);\n\nDECLARE @DQuery_Sep NVARCHAR(MAX) = \'\';\nSELECT	@DQuery_Sep = STRING_AGG( CONCAT( @DQuery_Sep, \'\nSELECT	\', RowNum, \' AS RowRef\n	,	STRING_AGG( TargetID, \'\'\', REPLACE( REPLACE( Separator\n	,	\'\'\'\', \'\'\'\'\'\' )\n	,	\'{C}\', TargetColumn )\n	,	\'\'\' ) AS ConSep\n	FROM ##TargetItem\'), \'\nUNION ALL\' )\n	FROM ##TargetTable\n		WHERE (1 = @IsForcedSep) OR (Separator IS NOT NULL)\n	\nDROP TABLE IF EXISTS ##TableSep;\nSET @DQuery_Sep = CONCAT(\'\nWITH CTE_ConSep AS\n( \', @DQuery_Sep, \'\n)\nSELECT *\nINTO ##TableSep\n	FROM CTE_ConSep\n\');\n\nIF( 0 < @IsDebug ) SELECT @DQuery_Sep AS [@DQuery_Sep]\nEXEC sp_ExecuteSQL @DQuery_Sep;\n\n-- 쿼리 작성 : 조회\nDECLARE @DQuery_SELECT NVARCHAR(MAX) = \'\';\nSELECT	@DQuery_SELECT = STRING_AGG( REPLACE( REPLACE( REPLACE( CONCAT( @DQuery_SELECT, \'\nSELECT	\', TD.RowNum, \' AS DBRow\n	,	\', TT.RowNum, \' AS TableRow\n	,	TSource.{C} AS TargetID\n	,	COUNT(TSource.{C}) AS TargetCount\n	FROM \', TD.TargetDB, \'.dbo.\',  TT.TableName,\' AS TSource\n		WHERE \', TT.FormatWhere, \'\n		GROUP BY TSource.{C}\')\n		,	\'{I}\', ISNULL(TS.ConSep, \'\'))\n		,	\'{T}\', TT.TableName)\n		,	\'{C}\', TT.TargetColumn)\n		, \'\nUNION ALL\')\n	FROM ##TargetDB AS TD\n		CROSS JOIN ##TargetTable AS TT\n		LEFT JOIN ##TableSep AS TS\n			ON TT.RowNum = TS.RowRef\n			\nSET @DQuery_SELECT = CONCAT(\'\nWITH CTE_Result AS\n( \', @DQuery_SELECT, \'\n)\nSELECT	TD.RowNum AS DBRow\n	,	TT.RowNum AS TableRow\n	,	TI.RowNum AS ItemRow\n	,	TD.TargetDB\n	,	TT.TableName AS TargetTable\n	,	TI.TargetID\n	,	ISNULL(TargetCount, 0) AS TargetCount\n	FROM CTE_Result AS CR\n		RIGHT JOIN ##TargetItem AS TI\n			ON	TI.TargetID = CR.TargetID\n		CROSS JOIN ##TargetDB AS TD\n		CROSS JOIN ##TargetTable AS TT\n		ORDER BY TD.RowNum, TT.RowNum, TI.RowNum\n\')\n\n-- 쿼리 작성 : 적용\nDECLARE @DQuery_PROCESS NVARCHAR(MAX) = \'\';\nSELECT	@DQuery_PROCESS = STRING_AGG( REPLACE( REPLACE( REPLACE( REPLACE( CONCAT( @DQuery_PROCESS, FormatProcess, \';\' )\n		,	\'{W}\', TT.FormatWhere)\n		,	\'{I}\', ISNULL(TS.ConSep, \'(ERROR)\'))\n		,	\'{T}\', CONCAT( TD.TargetDB, \'.dbo.\', TT.TableName ) )\n		,	\'{C}\', TT.TargetColumn)\n		,	\'\n\')\n	FROM ##TargetDB AS TD\n		CROSS JOIN ##TargetTable AS TT\n		LEFT JOIN ##TableSep AS TS\n			ON TT.RowNum = TS.RowRef\n\n-- 조회 : 적용 전\nIF( 0 < @IsDebug ) SELECT @DQuery_SELECT AS [@DQuery_SELECT]\nIF( 0 = @IsDebug ) EXEC sp_ExecuteSQL @DQuery_SELECT\n\nBEGIN TRY\nBEGIN TRAN\n\n	-- 적용 진행\n	IF( 0 < @IsDebug ) SELECT @DQuery_PROCESS AS [@DQuery_PROCESS]\n	IF( 0 = @IsDebug ) EXEC sp_ExecuteSQL @DQuery_PROCESS\n\n	-- 조회 : 적용 후\n	IF( 0 < @IsDebug ) SELECT @DQuery_SELECT AS [@DQuery_SELECT]\n	IF( 0 = @IsDebug ) EXEC sp_ExecuteSQL @DQuery_SELECT\n\n	IF( 0 < @IsCommit )\n	BEGIN\n		SELECT \'Run complate\' AS \'Do : COMMIT\';\n		COMMIT TRAN\n	END\n	ELSE\n	BEGIN\n		SELECT IIF( 0 < @IsCommit, \'Error on run\', \'Commit canceled ( 0 < @IsCommit )\') AS \'Do : ROLLBACK\';\n		ROLLBACK TRAN\n	END\n	\nEND TRY\nBEGIN CATCH\n		SELECT	\'Error on run\' AS \'Do : ROLLBACK\'\n			,	ERROR_MESSAGE() AS \'ErrorMessage\';\n		ROLLBACK TRAN\nEND CATCH'),
	(305, 5, 0, 13, 14, 'items', 'item_number', '521002249, 521002250, 521002251', 'USE master;\nGO\n/*\n\n서버명 : 전서버 대상\n\nQuestState\n- 1 : 진행\n- 2 : 완료\n- 3 : 포기\n*/\n\n-- [설정 : 적용 여부]\nDECLARE @IsCommit TINYINT = 1;\nDECLARE @IsDebug TINYINT = 0;\n\n-- [설정 : 대상 ID]\nDROP TABLE IF EXISTS ##TargetItem;\nCREATE TABLE ##TargetItem (\n	RowNum		INT IDENTITY(1, 1)		PRIMARY KEY\n,	TargetID	INT		-- ** 탐색할 ID 타입에 따라 변경 **\n);\nINSERT INTO ##TargetItem ( TargetID ) VALUES\n(521002249), (521002250), (521002251)\n\n-- [설정 : 대상 DB]\nDROP TABLE IF EXISTS ##TargetDB;\nCREATE TABLE ##TargetDB (\n	RowNum		INT IDENTITY(1, 1)		PRIMARY KEY\n,	TargetDB	VARCHAR(32)\n);\nINSERT INTO ##TargetDB (TargetDB) \nSELECT ServerName\n	FROM dk_game_integrate.dbo.ConnectInfo\n		WHERE	ServerGroupID IN ( 50, 53 )	-- 적용할 서버 그룹\n			AND	DB_ID( ServerName ) IS NOT NULL\n		ORDER BY WorldID\n\n-- [설정 : 대상 테이블, 탐색 양식]\nDROP TABLE IF EXISTS ##TargetTable;\nCREATE TABLE ##TargetTable (\n	RowNum			INT IDENTITY(1, 1)	PRIMARY KEY\n,	TableName		NVARCHAR(64)\n,	TargetColumn	NVARCHAR(64)\n,	FormatProcess	NVARCHAR(MAX)		-- {C}:[TargetColumn], {I}:TargetIDs, {T}:[TableName], {W}:[FormatWhere]\n,	FormatWhere		NVARCHAR(MAX)		-- {C}:[TargetColumn], {I}:TargetIDs, {T}:[TableName]\n,	Separator		VARCHAR(MAX)		-- {C}:[TargetColumn]\n);\n\nINSERT INTO ##TargetTable\n(	TableName, TargetColumn	-- 대상 테이블, 컬럼 명칭\n,	FormatProcess			-- 일괄 적용될 쿼리 양식\n,	FormatWhere				-- 조회, 적용 조건\n,	Separator				-- 구분자 (필요할 경우에만 입력)\n)\nVALUES\n(	\'Quest\', \'QuestID\'\n,	\'UPDATE {T} SET QuestState = 3 WHERE {W}\'\n,	\'{C} IN ( SELECT TargetID FROM ##TargetItem ) AND QuestState != 3\'\n,	NULL )\n--,(	\'SKID_ITEM_TB\', \'ITEMID\'\n--,	\'DELETE FROM {T} WHERE {W}\'\n--,	\'{C} LIKE \'\'{I}\'\'\'\n--,	\'\'\' OR {C} LIKE \'\'\' )\n;\n\n-- 쿼리 작성 : 구분자\nDECLARE @IsForcedSep TINYINT = IIF(EXISTS(SELECT TOP(1) * FROM ##TargetTable WHERE Separator IS NOT NULL), 0, 1);\n\nDECLARE @DQuery_Sep NVARCHAR(MAX) = \'\';\nSELECT	@DQuery_Sep = STRING_AGG( CONCAT( @DQuery_Sep, \'\nSELECT	\', RowNum, \' AS RowRef\n	,	STRING_AGG( TargetID, \'\'\', REPLACE( REPLACE( Separator\n	,	\'\'\'\', \'\'\'\'\'\' )\n	,	\'{C}\', TargetColumn )\n	,	\'\'\' ) AS ConSep\n	FROM ##TargetItem\'), \'\nUNION ALL\' )\n	FROM ##TargetTable\n		WHERE (1 = @IsForcedSep) OR (Separator IS NOT NULL)\n	\nDROP TABLE IF EXISTS ##TableSep;\nSET @DQuery_Sep = CONCAT(\'\nWITH CTE_ConSep AS\n( \', @DQuery_Sep, \'\n)\nSELECT *\nINTO ##TableSep\n	FROM CTE_ConSep\n\');\n\nIF( 0 < @IsDebug ) SELECT @DQuery_Sep AS [@DQuery_Sep]\nEXEC sp_ExecuteSQL @DQuery_Sep;\n\n-- 쿼리 작성 : 조회\nDECLARE @DQuery_SELECT NVARCHAR(MAX) = \'\';\nSELECT	@DQuery_SELECT = STRING_AGG( REPLACE( REPLACE( REPLACE( CONCAT( @DQuery_SELECT, \'\nSELECT	\', TD.RowNum, \' AS DBRow\n	,	\', TT.RowNum, \' AS TableRow\n	,	TSource.{C} AS TargetID\n	,	COUNT(TSource.{C}) AS TargetCount\n	FROM \', TD.TargetDB, \'.dbo.\',  TT.TableName,\' AS TSource\n		WHERE \', TT.FormatWhere, \'\n		GROUP BY TSource.{C}\')\n		,	\'{I}\', ISNULL(TS.ConSep, \'\'))\n		,	\'{T}\', TT.TableName)\n		,	\'{C}\', TT.TargetColumn)\n		, \'\nUNION ALL\')\n	FROM ##TargetDB AS TD\n		CROSS JOIN ##TargetTable AS TT\n		LEFT JOIN ##TableSep AS TS\n			ON TT.RowNum = TS.RowRef\n			\nSET @DQuery_SELECT = CONCAT(\'\nWITH CTE_Result AS\n( \', @DQuery_SELECT, \'\n)\nSELECT	TD.RowNum AS DBRow\n	,	TT.RowNum AS TableRow\n	,	TI.RowNum AS ItemRow\n	,	TD.TargetDB\n	,	TT.TableName AS TargetTable\n	,	TI.TargetID\n	,	ISNULL(TargetCount, 0) AS TargetCount\n	FROM CTE_Result AS CR\n		RIGHT JOIN ##TargetItem AS TI\n			ON	TI.TargetID = CR.TargetID\n		CROSS JOIN ##TargetDB AS TD\n		CROSS JOIN ##TargetTable AS TT\n		ORDER BY TD.RowNum, TT.RowNum, TI.RowNum\n\')\n\n-- 쿼리 작성 : 적용\nDECLARE @DQuery_PROCESS NVARCHAR(MAX) = \'\';\nSELECT	@DQuery_PROCESS = STRING_AGG( REPLACE( REPLACE( REPLACE( REPLACE( CONCAT( @DQuery_PROCESS, FormatProcess, \';\' )\n		,	\'{W}\', TT.FormatWhere)\n		,	\'{I}\', ISNULL(TS.ConSep, \'(ERROR)\'))\n		,	\'{T}\', CONCAT( TD.TargetDB, \'.dbo.\', TT.TableName ) )\n		,	\'{C}\', TT.TargetColumn)\n		,	\'\n\')\n	FROM ##TargetDB AS TD\n		CROSS JOIN ##TargetTable AS TT\n		LEFT JOIN ##TableSep AS TS\n			ON TT.RowNum = TS.RowRef\n\n-- 조회 : 적용 전\nIF( 0 < @IsDebug ) SELECT @DQuery_SELECT AS [@DQuery_SELECT]\nIF( 0 = @IsDebug ) EXEC sp_ExecuteSQL @DQuery_SELECT\n\nBEGIN TRY\nBEGIN TRAN\n\n	-- 적용 진행\n	IF( 0 < @IsDebug ) SELECT @DQuery_PROCESS AS [@DQuery_PROCESS]\n	IF( 0 = @IsDebug ) EXEC sp_ExecuteSQL @DQuery_PROCESS\n\n	-- 조회 : 적용 후\n	IF( 0 < @IsDebug ) SELECT @DQuery_SELECT AS [@DQuery_SELECT]\n	IF( 0 = @IsDebug ) EXEC sp_ExecuteSQL @DQuery_SELECT\n\n	IF( 0 < @IsCommit )\n	BEGIN\n		SELECT \'Run complate\' AS \'Do : COMMIT\';\n		COMMIT TRAN\n	END\n	ELSE\n	BEGIN\n		SELECT IIF( 0 < @IsCommit, \'Error on run\', \'Commit canceled ( 0 < @IsCommit )\') AS \'Do : ROLLBACK\';\n		ROLLBACK TRAN\n	END\n	\nEND TRY\nBEGIN CATCH\n		SELECT	\'Error on run\' AS \'Do : ROLLBACK\'\n			,	ERROR_MESSAGE() AS \'ErrorMessage\';\n		ROLLBACK TRAN\nEND CATCH'),
	(306, 6, 0, 5, 6, 'items', 'item_string', '20260721', '/*  ​\n점검 일정: 2026.07.21 (화) 오후 15:00\n ​\n 07/21 점검 시 젬 소비 이벤트 누적 데이터의 초기화가 필요하여 요청드립니다.\n ​\n 잘 부탁드립니다!\n*/\nUSE Joy1\n\nBEGIN TRANSACTION\n\nDECLARE @ExecuteDate NVARCHAR(16) = {{date}};\nDECLARE @IsCommit TINYINT = 0;		/*** 라이브 적용 시 값 변경 부탁드립니다 : [1] ***/\n\n-- 백업 쿼리 실행\nDECLARE @DQ_BackupTable NVARCHAR(MAX) = CONCAT( \'\nIF EXISTS(SELECT * FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_NAME=\'\'PayBackEvent_\', @ExecuteDate, \'\'\')\n	DROP Table dbo.PayBackEvent_\', @ExecuteDate, \';\nSELECT * INTO dbo.PayBackEvent_\', @ExecuteDate, \' FROM dbo.PayBackEvent WITH (TABLOCK)\n\' );\nEXEC sp_ExecuteSql @DQ_BackupTable;\n\nSELECT * FROM Joy1.dbo.PayBackEvent;\n\nBEGIN TRY\nDELETE FROM Joy1.dbo.PayBackEvent ;\nEND TRY\nBEGIN CATCH\nIF @@ERROR <> 0\nBEGIN\n	ROLLBACK TRANSACTION\n	RETURN\nEND\nEND CATCH\n\nSELECT * FROM Joy1.dbo.PayBackEvent\n\nIF (1 = @IsCommit)\nBEGIN\n	SELECT \'Run complete\' AS \'Do : COMMIT\';\n	COMMIT TRANSACTION\nEND\nELSE\nBEGIN\n	SELECT IIF( @IsCommit = 1, \'Error on delete\', \'Commit canceled ( @IsCommit = 0 )\') AS \'Do : ROLLBACK\';\n	ROLLBACK TRANSACTION\nEND'),
	(307, 7, 0, 15, 16, 'items', 'item_number', '0', 'USE `gunzgame`;\n\n-- {{items}}\n\nDROP TABLE IF EXISTS `Attendence_Temp`;\n\nRENAME TABLE `Attendence` TO `Attendence_Temp`;\n\nCREATE TABLE `Attendence` LIKE `Attendence_Temp`;');
