-- 테이블 dqpm.activity_log 구조 내보내기
CREATE TABLE IF NOT EXISTS `activity_log` (
  `n_id` bigint NOT NULL COMMENT 'JSON nId',
  `dt_at` datetime(6) NOT NULL,
  `str_method` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `str_path` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL,
  `n_status_code` int NOT NULL,
  `n_actor_user_id` int DEFAULT NULL,
  `str_actor_user_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `str_category` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'auth|event|user|ops|other',
  `json_actor_roles` json DEFAULT NULL COMMENT 'arrActorRoles[]',
  PRIMARY KEY (`n_id`),
  KEY `idx_al_dt` (`dt_at`),
  KEY `idx_al_cat_dt` (`str_category`,`dt_at`),
  KEY `idx_al_actor` (`n_actor_user_id`,`dt_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='activity_logs.json';

-- 테이블 데이터 dqpm.activity_log:~2,501 rows (대략적) 내보내기

-- 테이블 dqpm.db_connection 구조 내보내기
CREATE TABLE IF NOT EXISTS `db_connection` (
  `n_id` int NOT NULL COMMENT 'JSON nId',
  `n_product_id` int NOT NULL,
  `str_product_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `n_service_id` bigint DEFAULT NULL COMMENT 'product_service.n_id, NULL=공통',
  `str_service_abbr` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'denormalized strAbbr',
  `str_kind` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'GAME' COMMENT 'GAME|WEB|LOG',
  `str_env` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'dev|qa|live',
  `str_db_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'mssql|mysql',
  `str_host` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `n_port` int NOT NULL,
  `str_database` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `str_user` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `str_password` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '평문·암호화 정책은 앱 레벨',
  `b_is_active` tinyint(1) NOT NULL DEFAULT '1',
  `dt_created_at` datetime(6) NOT NULL,
  `dt_updated_at` datetime(6) NOT NULL,
  PRIMARY KEY (`n_id`),
  KEY `idx_db_connection_product_env` (`n_product_id`,`str_env`,`b_is_active`),
  KEY `idx_db_connection_product_service_env` (`n_product_id`,`str_service_abbr`,`str_env`,`b_is_active`),
  KEY `idx_db_connection_service` (`n_service_id`),
  CONSTRAINT `fk_db_connection_product` FOREIGN KEY (`n_product_id`) REFERENCES `product` (`n_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='dbConnections.json';

-- 테이블 데이터 dqpm.db_connection:~16 rows (대략적) 내보내기

-- 테이블 dqpm.event_instance 구조 내보내기
CREATE TABLE IF NOT EXISTS `event_instance` (
  `n_id` int NOT NULL COMMENT 'JSON nId',
  `n_event_template_id` int NOT NULL,
  `n_product_id` int NOT NULL,
  `n_service_id` bigint DEFAULT NULL COMMENT 'product_service.n_id',
  `str_event_label` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL,
  `str_product_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `str_service_abbr` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `str_service_region` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `str_category` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `str_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `str_event_name` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL,
  `str_input_values` text COLLATE utf8mb4_unicode_ci,
  `str_generated_query` mediumtext COLLATE utf8mb4_unicode_ci,
  `dt_deploy_date` datetime(6) NOT NULL COMMENT 'JSON dtDeployDate',
  `dt_qa_deploy_date` datetime(6) DEFAULT NULL,
  `dt_live_deploy_date` datetime(6) DEFAULT NULL,
  `str_allo_link` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `str_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `str_created_by` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `n_created_by_user_id` int NOT NULL,
  `dt_created_at` datetime(6) NOT NULL,
  `b_permanently_removed` tinyint(1) NOT NULL DEFAULT '0',
  `dt_permanently_removed_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`n_id`),
  KEY `fk_ei_template` (`n_event_template_id`),
  KEY `idx_ei_status` (`str_status`),
  KEY `idx_ei_product` (`n_product_id`),
  KEY `idx_ei_service` (`n_service_id`),
  KEY `idx_ei_created_by` (`n_created_by_user_id`),
  KEY `idx_ei_created_at` (`dt_created_at`),
  CONSTRAINT `fk_ei_creator_user` FOREIGN KEY (`n_created_by_user_id`) REFERENCES `users` (`n_id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_ei_product` FOREIGN KEY (`n_product_id`) REFERENCES `product` (`n_id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_ei_template` FOREIGN KEY (`n_event_template_id`) REFERENCES `event_template` (`n_id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='eventInstances.json 스칼라 필드';

-- 테이블 데이터 dqpm.event_instance:~3 rows (대략적) 내보내기

