CREATE TABLE IF NOT EXISTS `event_instance_deploy_scope` (
  `n_instance_id` int NOT NULL,
  `str_scope` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'qa | live',
