-- 테이블 dqpm.event_template 구조 내보내기
CREATE TABLE IF NOT EXISTS `event_template` (
  `n_id` int NOT NULL COMMENT 'JSON nId',
  `n_product_id` int NOT NULL,
  `str_product_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `str_event_label` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL,
  `str_description` text COLLATE utf8mb4_unicode_ci,
  `str_category` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `str_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `str_input_format` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `str_default_items` text COLLATE utf8mb4_unicode_ci COMMENT '레거시 단일 필드',
  `str_query_template` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '레거시 단일 필드(세트 사용 시 비움)',
  `str_created_by` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'JSON strCreatedBy',
  `n_created_by_user_id` int DEFAULT NULL COMMENT 'JSON nCreatedByUserId',
  `dt_created_at` datetime(6) NOT NULL,
  `str_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'dba_confirmed' COMMENT 'template_created|confirm_requested|dba_confirmed',
  `json_status_logs` json NOT NULL COMMENT 'ITemplateStatusLog[]',
  `json_creator` json DEFAULT NULL COMMENT 'ITemplateStageActor objCreator',
  `json_confirmer` json DEFAULT NULL COMMENT 'ITemplateStageActor objConfirmer',
  PRIMARY KEY (`n_id`),
  KEY `fk_event_template_creator` (`n_created_by_user_id`),
  KEY `idx_event_template_product` (`n_product_id`),
  KEY `idx_event_template_status` (`str_status`),
  CONSTRAINT `fk_event_template_creator` FOREIGN KEY (`n_created_by_user_id`) REFERENCES `users` (`n_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_event_template_product` FOREIGN KEY (`n_product_id`) REFERENCES `product` (`n_id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='events.json 본문(세트 제외)';

